                        <EyeIcon aria-hidden="true" />
                      )}
                    </InputGroupButton>
                  </InputGroupAddon>
                </InputGroup>
                {loginError ? (
                  <FieldError id="login-error">{loginError}</FieldError>
                ) : null}
              </Field>

              <Button
