                  "Continue"
                )}
              </Button>
            </FieldGroup>
          </form>
        </DialogContent>
      </Dialog>

      {/* Step 2: OTP, stacked on top of the login dialog */}
      <Dialog open={otpOpen} onOpenChange={handleOtpOpenChange}>
        <DialogContent
