                  <InputOTPSlot
                    index={1}
                    aria-invalid={otpError ? true : undefined}
                    className="size-10 sm:size-11"
                  />
                  <InputOTPSlot
                    index={2}
                    aria-invalid={otpError ? true : undefined}
                    className="size-10 sm:size-11"
                  />
                </InputOTPGroup>
